            C++

    #include <stdio.h>

int main()
{
    FILE *fp = fopen("file.txt", "r");
    char buffer[100];

    if (fp == NULL) {
        printf("Unable to open file.");
        return 1;
    }

    while (fgets(buffer, sizeof(buffer), fp))
        printf("%s", buffer);

    fclose(fp);

    return 0;
}

