            C++

    #include <stdio.h>

int main()
{
    FILE *fp = fopen("file.txt", "r");

    char name[50];
    int age;

    if (fp == NULL) {
        printf("Unable to open file.");
        return 1;
    }

    while (fscanf(fp, "%s %d", name, &age) == 2)
        printf("Name: %s  Age: %d\n", name, age);

    fclose(fp);

    return 0;
}

